 INSERT INTO exams (title,description,category,module,duration_minutes,marks_per_question,negative_mark,is_live,rules) VALUES ('Academic Reading Practice 1','Original full-length reading practice with 40 questions, authentic timing and mixed IELTS question types.','Academic Practice Library','reading',60,1,0,true,'{"showExplanations":true}'::jsonb) RETURNING id INTO eid;
 INSERT INTO sections (exam_id,title,passage_title,passage_text,instruction,audio_url,sort_order) VALUES (eid,'Passage 1','When Wetlands Return to the City','For much of the twentieth century, urban wetlands were treated as inconvenient obstacles to construction. Draining them created land for roads and housing, but it also removed a natural system that had absorbed heavy rainfall. As cities expanded, water that once disappeared into marshy ground rushed into drains instead, increasing the risk of flash floods.
 INSERT INTO questions (exam_id,section_id,qtype,text,option_a,option_b,option_c,option_d,correct_option,accepted_answers,explanation,sort_order) VALUES
  (eid,s1,'tfng','Early urban development often involved draining wetlands.','','','','',0,'','The passage says draining created land for roads and housing.',1),
  (eid,s1,'tfng','Restored wetlands always eliminate flooding completely.','','','','',1,'','Restored wetlands reduce risk, but the passage does not claim they eliminate all flooding.',2),
  (eid,s1,'tfng','Residents never encounter wildlife in restored wetlands.','','','','',1,'','The passage explicitly describes roots creating spaces for moisture.',3),
  (eid,s1,'mcq','Why were wetlands drained in many cities?','To create space for construction','To attract more birds','To improve drinking water','To reduce road traffic',0,'','The passage says draining created land for roads and housing.',4),
  (eid,s1,'mcq','What is one cause of increased flash-flood risk?','More wetlands','Water rushing into drains','Additional tree roots','More public parks',1,'','Restored wetlands reduce risk, but the passage does not claim they eliminate all flooding.',5),
  (eid,s1,'mcq','What do aquatic plant roots do?','Raise air temperature','Create spaces where moisture collects','Stop all soil erosion','Remove every pollutant',1,'','The passage explicitly describes roots creating spaces for moisture.',6),
  (eid,s1,'mcq','Who may assist with monitoring restored sites?','Only tourists','Local volunteers','Construction companies only','International airlines',1,'','Costs are described generally, not as exact figures for every project.',7),
  (eid,s1,'gap','Complete the summary with ONE OR TWO words: Draining wetlands created land for roads and ______.','','','','',0,'housing|houses','The passage says draining created land for roads and housing.',8),
  (eid,s1,'gap','Complete the summary with ONE OR TWO words: Reeds and aquatic plants slow the movement of ______.','','','','',0,'water|rainwater','Restored wetlands reduce risk, but the passage does not claim they eliminate all flooding.',9),
  (eid,s1,'gap','Complete the summary with ONE OR TWO words: The roots create spaces in the soil where ______ can collect.','','','','',0,'moisture|water','The passage explicitly describes roots creating spaces for moisture.',10),
  (eid,s1,'gap','Complete the summary with ONE OR TWO words: Local volunteers often help monitor plants and ______.','','','','',0,'animals|animal species','Costs are described generally, not as exact figures for every project.',11),
  (eid,s1,'matching','Choose the most suitable heading for this passage.','The hidden cost of building on wetlands','A complete history of urban transport','Why cities should ban agriculture','The commercial value of rare birds',0,'','The correct heading captures the passage''s main subject and purpose.',12),
  (eid,s1,'dnd','Arrange the following stages in the order described in the passage.','Drainage of natural wetlands','Expansion of impermeable city surfaces','Restoration of aquatic habitats','Monitoring by engineers and volunteers',0,'0,1,2,3','The stages follow the sequence presented in the passage.',13);
 INSERT INTO sections (exam_id,title,passage_title,passage_text,instruction,audio_url,sort_order) VALUES (eid,'Passage 2','Sleep and the Work of Memory','Sleep is sometimes described as a period in which the brain simply switches off. Research suggests a more complicated picture. During the night, the brain cycles through several stages, and each appears to contribute differently to learning and emotional regulation.
 INSERT INTO questions (exam_id,section_id,qtype,text,option_a,option_b,option_c,option_d,correct_option,accepted_answers,explanation,sort_order) VALUES
  (eid,s2,'tfng','The brain passes through different stages during sleep.','','','','',0,'','The opening section states that the brain cycles through several stages.',14),
  (eid,s2,'tfng','Skill-related brain activity may reappear during sleep.','','','','',0,'','The memory section describes replay strengthening useful connections.',15),
  (eid,s2,'tfng','One short night permanently destroys all memories.','','','','',1,'','The passage says one short night does not destroy memory, but repeated loss reduces efficiency.',16),
  (eid,s2,'mcq','What happens to brain activity during sleep?','It follows several stages','It stops completely','It remains identical all night','It only controls muscles',0,'','The opening section states that the brain cycles through several stages.',17),
  (eid,s2,'mcq','What may happen after a person practises a skill?','The skill is forgotten immediately','Related brain activity may replay during sleep','Attention becomes unnecessary','All memories become permanent',1,'','The memory section describes replay strengthening useful connections.',18),
  (eid,s2,'mcq','What can repeated sleep loss do?','Make learning less efficient','Guarantee better recall','Remove the need for practice','Prevent emotional regulation',0,'','The passage says one short night does not destroy memory, but repeated loss reduces efficiency.',19),
  (eid,s2,'mcq','What routine do researchers recommend?','Irregular sleep times','Consistent sleep routines','Only weekend sleep','No nightly routine',1,'','The passage says lapses can occur without awareness.',20),
  (eid,s2,'gap','Complete the summary with ONE OR TWO words: During the night, the brain cycles through several ______.','','','','',0,'stages|sleep stages','The opening section states that the brain cycles through several stages.',21),
  (eid,s2,'gap','Complete the summary with ONE OR TWO words: Replay is thought to strengthen useful ______.','','','','',0,'connections|brain connections','The memory section describes replay strengthening useful connections.',22),
  (eid,s2,'gap','Complete the summary with ONE OR TWO words: Repeated sleep loss can make learning less ______.','','','','',0,'efficient','The passage says one short night does not destroy memory, but repeated loss reduces efficiency.',23),
  (eid,s2,'gap','Complete the summary with ONE OR TWO words: Brief attention lapses can occur without a person''s ______.','','','','',0,'awareness|knowledge','The passage says lapses can occur without awareness.',24),
  (eid,s2,'matching','Choose the most suitable heading for this passage.','Why sleep is unnecessary for adults','The active role of sleep in learning','A history of alarm clocks','The best weekend entertainment',1,'','The correct heading captures the passage''s main subject and purpose.',25),
  (eid,s2,'dnd','Arrange the following stages in the order described in the passage.','Practice of a new skill','Replay of related brain activity','Strengthening of memory connections','More reliable recall',0,'0,1,2,3','The stages follow the sequence presented in the passage.',26);
 INSERT INTO sections (exam_id,title,passage_title,passage_text,instruction,audio_url,sort_order) VALUES (eid,'Passage 3','The Growing Repair Economy','Repairing a damaged appliance was once an ordinary part of household life. As mass-produced goods became cheaper, replacement often appeared easier than finding spare parts or a skilled technician. The resulting waste created pressure on landfill sites and increased demand for raw materials.
 INSERT INTO questions (exam_id,section_id,qtype,text,option_a,option_b,option_c,option_d,correct_option,accepted_answers,explanation,sort_order) VALUES
  (eid,s3,'tfng','Cheaper replacement goods contributed to a decline in repair.','','','','',0,'','The introduction links cheaper goods with more replacement and waste.',27),
  (eid,s3,'tfng','Repair cafés only allow professional technicians to handle objects.','','','','',1,'','Owners work with volunteers rather than merely watching professionals.',28),
  (eid,s3,'tfng','Failure records can provide information to manufacturers.','','','','',0,'','The passage says failure information can be useful to manufacturers and campaigners.',29),
  (eid,s3,'mcq','Why did replacement become more attractive?','Mass-produced goods became cheaper','Technicians became more common','Landfill sites disappeared','Manuals became easier to read',0,'','The introduction links cheaper goods with more replacement and waste.',30),
  (eid,s3,'mcq','What do visitors do at repair cafés?','Watch without participating','Work alongside volunteers','Buy only new products','Manufacture spare parts',1,'','Owners work with volunteers rather than merely watching professionals.',31),
  (eid,s3,'mcq','What additional benefit can repair-café records provide?','Weather forecasts','Information about product failure','Free international shipping','New landfill locations',1,'','The passage says failure information can be useful to manufacturers and campaigners.',32),
  (eid,s3,'mcq','What concern do critics of right-to-repair mention?','Safety and intellectual property','Excessive rainfall','A shortage of volunteers','Too much wildlife',0,'','The passage discusses several regions but gives no claim of identical laws everywhere.',33),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Replacement increased demand for raw ______.','','','','',0,'materials|raw materials','The introduction links cheaper goods with more replacement and waste.',34),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Visitors work alongside ______ who share tools and knowledge.','','','','',0,'volunteers|the volunteers','Owners work with volunteers rather than merely watching professionals.',35),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Some cafés record the reasons for ______.','','','','',0,'failure|product failure','The passage says failure information can be useful to manufacturers and campaigners.',36),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Supporters say longer product ______ benefit consumers and the environment.','','','','',0,'lifetimes|lifetime|lives','The passage discusses several regions but gives no claim of identical laws everywhere.',37),
  (eid,s3,'matching','Choose the most suitable heading for this passage.','Why landfill is no longer a problem','Repair as practical and environmental action','The disappearance of all technicians','A guide to buying more appliances',1,'','The correct heading captures the passage''s main subject and purpose.',38),
  (eid,s3,'dnd','Arrange the following stages in the order described in the passage.','A product fails','Owner visits a repair café','Volunteer and owner investigate it','Failure information is recorded',0,'0,1,2,3','The stages follow the sequence presented in the passage.',39),
  (eid,s3,'mcq','What is the writer''s or speaker''s main purpose?','To discuss how repair can reduce waste and build skills','To advertise a new appliance','To oppose all manufacturing','To compare international tax systems',0,'','This option best summarises the overall purpose rather than a minor detail.',40);
