 INSERT INTO sections (exam_id,title,passage_title,passage_text,instruction,audio_url,sort_order) VALUES (eid,'Passage 3','Citizen Science Beyond the Laboratory','Scientific research does not always require a laboratory coat or an expensive institution. Citizen-science projects invite members of the public to collect observations, classify images or measure local conditions. With suitable training and clear protocols, volunteers can gather data across far wider areas than a small professional team could cover.
 INSERT INTO questions (exam_id,section_id,qtype,text,option_a,option_b,option_c,option_d,correct_option,accepted_answers,explanation,sort_order) VALUES
  (eid,s3,'tfng','Citizen science can cover areas difficult for a small professional team to reach.','','','','',0,'','The first section links volunteer coverage with training and protocols.',27),
  (eid,s3,'tfng','Bird counts can reveal changes in species distribution.','','','','',0,'','The bird-count example explicitly mentions changes in distribution.',28),
  (eid,s3,'tfng','Volunteer datasets require no checking.','','','','',1,'','The final section stresses careful checking by experienced reviewers.',29),
  (eid,s3,'mcq','What advantage can volunteers provide?','Wider geographic coverage','Guaranteed perfect data','Elimination of training','Less need for protocols',0,'','The first section links volunteer coverage with training and protocols.',30),
  (eid,s3,'mcq','What can coordinated bird counts help identify?','Changes in distribution over time','The price of telescopes','New road designs','The age of every participant',0,'','The bird-count example explicitly mentions changes in distribution.',31),
  (eid,s3,'mcq','How do organisers handle unusual records?','Delete every submission','Ask experienced reviewers to inspect them','Publish without review','Hide them from researchers',1,'','The final section stresses careful checking by experienced reviewers.',32),
  (eid,s3,'mcq','What encourages continued participation?','Understanding how observations are used','Keeping results secret','Removing all training','Avoiding feedback',0,'','The passage links understanding and feedback with continued involvement, not its frequency.',33),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Volunteers need suitable training and clear ______.','','','','',0,'protocols|a protocol','The first section links volunteer coverage with training and protocols.',34),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Participants record bird ______ on the same weekend.','','','','',0,'species|bird species','The bird-count example explicitly mentions changes in distribution.',35),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Experienced ______ may inspect unusual records.','','','','',0,'reviewers|reviewer','The final section stresses careful checking by experienced reviewers.',36),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Feedback can improve the quality of future ______.','','','','',0,'submissions|observations','The passage links understanding and feedback with continued involvement, not its frequency.',37),
  (eid,s3,'matching','Choose the most suitable heading for this passage.','Public participation in scientific discovery','Why professional science has ended','A guide to laboratory equipment','The history of weekend entertainment',0,'','The correct heading captures the passage''s main subject and purpose.',38),
  (eid,s3,'dnd','Arrange the following stages in the order described in the passage.','Volunteers receive a protocol','Observations are collected','Unusual records are reviewed','Contributors receive feedback',0,'0,1,2,3','The stages follow the sequence presented in the passage.',39),
  (eid,s3,'mcq','What is the writer''s or speaker''s main purpose?','To explain how volunteers contribute to research','To argue against professional scientists','To describe a single bird species','To promote a telescope brand',0,'','This option best summarises the overall purpose rather than a minor detail.',40);
