 INSERT INTO sections (exam_id,title,passage_title,passage_text,instruction,audio_url,sort_order) VALUES (eid,'Passage 3','Growing Food with Less Water','Agriculture in dry regions has always depended on careful management of water. Traditional farmers selected planting dates around seasonal rain and shaped fields to reduce runoff. Modern projects are combining such knowledge with sensors that measure soil moisture.
 INSERT INTO questions (exam_id,section_id,qtype,text,option_a,option_b,option_c,option_d,correct_option,accepted_answers,explanation,sort_order) VALUES
  (eid,s3,'tfng','Traditional farmers sometimes shaped fields to reduce runoff.','','','','',0,'','The first section explicitly mentions shaping fields and modern sensors.',27),
  (eid,s3,'tfng','Drip irrigation sprays water over the whole field.','','','','',1,'','The passage contrasts root delivery with spraying an entire field.',28),
  (eid,s3,'tfng','Maintenance can affect the performance of drip systems.','','','','',0,'','Blocked nozzles and poor maintenance are named as limitations.',29),
  (eid,s3,'mcq','What modern tool is combined with traditional knowledge?','Soil-moisture sensors','Aircraft engines','Traffic cameras','Hospital scanners',0,'','The first section explicitly mentions shaping fields and modern sensors.',30),
  (eid,s3,'mcq','Where does drip irrigation deliver water?','Into the air','Close to plant roots','Onto nearby roads','Only into storage tanks',1,'','The passage contrasts root delivery with spraying an entire field.',31),
  (eid,s3,'mcq','What can limit drip irrigation?','Blocked nozzles and poor maintenance','Too much training','Local spare parts','Healthy soil',0,'','Blocked nozzles and poor maintenance are named as limitations.',32),
