 INSERT INTO sections (exam_id,title,passage_title,passage_text,instruction,audio_url,sort_order) VALUES (eid,'Passage 3','When Wetlands Return to the City','For much of the twentieth century, urban wetlands were treated as inconvenient obstacles to construction. Draining them created land for roads and housing, but it also removed a natural system that had absorbed heavy rainfall. As cities expanded, water that once disappeared into marshy ground rushed into drains instead, increasing the risk of flash floods.
 INSERT INTO questions (exam_id,section_id,qtype,text,option_a,option_b,option_c,option_d,correct_option,accepted_answers,explanation,sort_order) VALUES
  (eid,s3,'tfng','Early urban development often involved draining wetlands.','','','','',0,'','The passage says draining created land for roads and housing.',27),
  (eid,s3,'tfng','Restored wetlands always eliminate flooding completely.','','','','',1,'','Restored wetlands reduce risk, but the passage does not claim they eliminate all flooding.',28),
  (eid,s3,'tfng','Residents never encounter wildlife in restored wetlands.','','','','',1,'','The passage explicitly describes roots creating spaces for moisture.',29),
  (eid,s3,'mcq','Why were wetlands drained in many cities?','To create space for construction','To attract more birds','To improve drinking water','To reduce road traffic',0,'','The passage says draining created land for roads and housing.',30),
  (eid,s3,'mcq','What is one cause of increased flash-flood risk?','More wetlands','Water rushing into drains','Additional tree roots','More public parks',1,'','Restored wetlands reduce risk, but the passage does not claim they eliminate all flooding.',31),
  (eid,s3,'mcq','What do aquatic plant roots do?','Raise air temperature','Create spaces where moisture collects','Stop all soil erosion','Remove every pollutant',1,'','The passage explicitly describes roots creating spaces for moisture.',32),
  (eid,s3,'mcq','Who may assist with monitoring restored sites?','Only tourists','Local volunteers','Construction companies only','International airlines',1,'','Costs are described generally, not as exact figures for every project.',33),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Draining wetlands created land for roads and ______.','','','','',0,'housing|houses','The passage says draining created land for roads and housing.',34),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Reeds and aquatic plants slow the movement of ______.','','','','',0,'water|rainwater','Restored wetlands reduce risk, but the passage does not claim they eliminate all flooding.',35),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: The roots create spaces in the soil where ______ can collect.','','','','',0,'moisture|water','The passage explicitly describes roots creating spaces for moisture.',36),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Local volunteers often help monitor plants and ______.','','','','',0,'animals|animal species','Costs are described generally, not as exact figures for every project.',37),
  (eid,s3,'matching','Choose the most suitable heading for this passage.','The hidden cost of building on wetlands','A complete history of urban transport','Why cities should ban agriculture','The commercial value of rare birds',0,'','The correct heading captures the passage''s main subject and purpose.',38),
  (eid,s3,'dnd','Arrange the following stages in the order described in the passage.','Drainage of natural wetlands','Expansion of impermeable city surfaces','Restoration of aquatic habitats','Monitoring by engineers and volunteers',0,'0,1,2,3','The stages follow the sequence presented in the passage.',39),
  (eid,s3,'mcq','What is the writer''s or speaker''s main purpose?','To explain why wetland restoration can benefit cities','To describe a single engineering experiment','To criticise all urban development','To compare bird migration routes',0,'','This option best summarises the overall purpose rather than a minor detail.',40);
