 INSERT INTO sections (exam_id,title,passage_title,passage_text,instruction,audio_url,sort_order) VALUES (eid,'Passage 3','The Growing Repair Economy','Repairing a damaged appliance was once an ordinary part of household life. As mass-produced goods became cheaper, replacement often appeared easier than finding spare parts or a skilled technician. The resulting waste created pressure on landfill sites and increased demand for raw materials.
 INSERT INTO questions (exam_id,section_id,qtype,text,option_a,option_b,option_c,option_d,correct_option,accepted_answers,explanation,sort_order) VALUES
  (eid,s3,'tfng','Cheaper replacement goods contributed to a decline in repair.','','','','',0,'','The introduction links cheaper goods with more replacement and waste.',27),
  (eid,s3,'tfng','Repair cafés only allow professional technicians to handle objects.','','','','',1,'','Owners work with volunteers rather than merely watching professionals.',28),
  (eid,s3,'tfng','Failure records can provide information to manufacturers.','','','','',0,'','The passage says failure information can be useful to manufacturers and campaigners.',29),
  (eid,s3,'mcq','Why did replacement become more attractive?','Mass-produced goods became cheaper','Technicians became more common','Landfill sites disappeared','Manuals became easier to read',0,'','The introduction links cheaper goods with more replacement and waste.',30),
  (eid,s3,'mcq','What do visitors do at repair cafés?','Watch without participating','Work alongside volunteers','Buy only new products','Manufacture spare parts',1,'','Owners work with volunteers rather than merely watching professionals.',31),
  (eid,s3,'mcq','What additional benefit can repair-café records provide?','Weather forecasts','Information about product failure','Free international shipping','New landfill locations',1,'','The passage says failure information can be useful to manufacturers and campaigners.',32),
  (eid,s3,'mcq','What concern do critics of right-to-repair mention?','Safety and intellectual property','Excessive rainfall','A shortage of volunteers','Too much wildlife',0,'','The passage discusses several regions but gives no claim of identical laws everywhere.',33),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Replacement increased demand for raw ______.','','','','',0,'materials|raw materials','The introduction links cheaper goods with more replacement and waste.',34),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Visitors work alongside ______ who share tools and knowledge.','','','','',0,'volunteers|the volunteers','Owners work with volunteers rather than merely watching professionals.',35),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Some cafés record the reasons for ______.','','','','',0,'failure|product failure','The passage says failure information can be useful to manufacturers and campaigners.',36),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: Supporters say longer product ______ benefit consumers and the environment.','','','','',0,'lifetimes|lifetime|lives','The passage discusses several regions but gives no claim of identical laws everywhere.',37),
  (eid,s3,'matching','Choose the most suitable heading for this passage.','Why landfill is no longer a problem','Repair as practical and environmental action','The disappearance of all technicians','A guide to buying more appliances',1,'','The correct heading captures the passage''s main subject and purpose.',38),
  (eid,s3,'dnd','Arrange the following stages in the order described in the passage.','A product fails','Owner visits a repair café','Volunteer and owner investigate it','Failure information is recorded',0,'0,1,2,3','The stages follow the sequence presented in the passage.',39),
  (eid,s3,'mcq','What is the writer''s or speaker''s main purpose?','To discuss how repair can reduce waste and build skills','To advertise a new appliance','To oppose all manufacturing','To compare international tax systems',0,'','This option best summarises the overall purpose rather than a minor detail.',40);
 INSERT INTO exams (title,description,category,module,duration_minutes,marks_per_question,negative_mark,is_live,rules) VALUES ('IELTS Listening Practice 1','Original full-length listening practice with 40 questions, authentic timing and mixed IELTS question types.','Listening Practice Library','listening',32,1,0,true,'{"showExplanations":true}'::jsonb) RETURNING id INTO eid;
 INSERT INTO sections (exam_id,title,passage_title,passage_text,instruction,audio_url,sort_order) VALUES (eid,'Section 1','Community Sports Centre Enquiry','Receptionist: Good morning, Riverside Sports Centre. New members are welcome to visit for a free tour on weekday evenings. Our swimming pool opens at six in the morning, while the main sports hall opens at eight.
 INSERT INTO questions (exam_id,section_id,qtype,text,option_a,option_b,option_c,option_d,correct_option,accepted_answers,explanation,sort_order) VALUES
  (eid,s1,'tfng','Free tours are available on weekday evenings.','','','','',0,'','The receptionist offers free tours on weekday evenings.',1),
  (eid,s1,'tfng','Court hire includes rackets at no extra charge.','','','','',1,'','Nets are included, but rackets cost three pounds each.',2),
  (eid,s1,'tfng','Online booking before noon reduces the evening court price.','','','','',0,'','The receptionist quotes twelve pounds instead of fifteen for qualifying online bookings.',3),
  (eid,s1,'mcq','When can new members take a free tour?','Weekday evenings','Sunday mornings only','Only at midnight','Every public holiday',0,'','The receptionist offers free tours on weekday evenings.',4),
  (eid,s1,'mcq','What does court hire include?','Rackets','Nets','Indoor shoes','Car parking',1,'','Nets are included, but rackets cost three pounds each.',5),
  (eid,s1,'mcq','How much is the discounted evening court?','Three pounds','Twelve pounds','Fifteen pounds','Twenty pounds',1,'','The receptionist quotes twelve pounds instead of fifteen for qualifying online bookings.',6),
  (eid,s1,'mcq','Where is the car park?','In front of the pool','Behind the centre','Beside the railway','Under the sports hall',1,'','The first two hours are free, not charged.',7),
  (eid,s1,'gap','Complete the summary with ONE OR TWO words: The swimming pool opens at ______ in the morning.','','','','',0,'six|6|6 am|six am','The receptionist offers free tours on weekday evenings.',8),
  (eid,s1,'gap','Complete the summary with ONE OR TWO words: Each racket costs ______ pounds to rent.','','','','',0,'three|3','Nets are included, but rackets cost three pounds each.',9),
  (eid,s1,'gap','Complete the summary with ONE OR TWO words: Booking online before ______ gives the lower price.','','','','',0,'noon|12 noon|midday','The receptionist quotes twelve pounds instead of fifteen for qualifying online bookings.',10);
 INSERT INTO sections (exam_id,title,passage_title,passage_text,instruction,audio_url,sort_order) VALUES (eid,'Section 2','Choosing a University Course','Tutor: Before you select your modules, consider how you prefer to learn. The environmental-science course has one lecture and one field workshop each week. Assessment is sixty per cent coursework and forty per cent examination.
 INSERT INTO questions (exam_id,section_id,qtype,text,option_a,option_b,option_c,option_d,correct_option,accepted_answers,explanation,sort_order) VALUES
  (eid,s2,'tfng','The course includes a weekly field workshop.','','','','',0,'','The tutor describes one lecture and one field workshop weekly.',11),
  (eid,s2,'tfng','Most of the assessment is based on the examination.','','','','',1,'','Coursework is sixty per cent and examination forty per cent.',12),
  (eid,s2,'tfng','Statistics support is available on Thursday afternoons.','','','','',0,'','The tutor offers a Thursday support class and a library copy.',13),
  (eid,s2,'mcq','How many lectures are there each week?','One','Two','Three','Four',0,'','The tutor describes one lecture and one field workshop weekly.',14),
  (eid,s2,'mcq','What proportion is coursework?','Forty per cent','Fifty per cent','Sixty per cent','Eighty per cent',2,'','Coursework is sixty per cent and examination forty per cent.',15),
  (eid,s2,'mcq','Where can the student get the recommended textbook?','From the library','Only from the tutor','At the coastal reserve','It is unavailable',0,'','The tutor offers a Thursday support class and a library copy.',16),
  (eid,s2,'mcq','What should the student bring?','Waterproof boots and a notebook','A tent and cooking equipment','A new laptop','Measuring equipment',0,'','The tutor says measuring equipment is provided.',17),
  (eid,s2,'gap','Complete the summary with ONE OR TWO words: There is one lecture and one field ______ each week.','','','','',0,'workshop|field workshop','The tutor describes one lecture and one field workshop weekly.',18),
  (eid,s2,'gap','Complete the summary with ONE OR TWO words: The examination accounts for ______ per cent.','','','','',0,'forty|40|40 per cent|forty per cent','Coursework is sixty per cent and examination forty per cent.',19),
  (eid,s2,'gap','Complete the summary with ONE OR TWO words: The first field trip is on the second ______ of term.','','','','',0,'Friday|friday','The tutor offers a Thursday support class and a library copy.',20);
 INSERT INTO sections (exam_id,title,passage_title,passage_text,instruction,audio_url,sort_order) VALUES (eid,'Section 3','A Guided Museum Visit','Guide: Welcome to the City Museum. Today’s highlights tour begins in the transport gallery on the ground floor. Please leave large bags in the free lockers beside the entrance. Photography is allowed without flash.
 INSERT INTO questions (exam_id,section_id,qtype,text,option_a,option_b,option_c,option_d,correct_option,accepted_answers,explanation,sort_order) VALUES
  (eid,s3,'tfng','Large bags can be left in free lockers.','','','','',0,'','The guide directs visitors to free lockers beside the entrance.',21),
  (eid,s3,'tfng','Flash photography is permitted everywhere.','','','','',1,'','Photography is allowed only without flash.',22),
  (eid,s3,'tfng','The tour spends twenty minutes at the clock exhibition.','','','','',0,'','The guide specifies twenty minutes in Room 14 before the café.',23),
  (eid,s3,'mcq','Where are the lockers?','Beside the entrance','In Room 14','Next to the café','On the second floor',0,'','The guide directs visitors to free lockers beside the entrance.',24),
  (eid,s3,'mcq','What photography rule applies?','No photography','Photography without flash','Flash is required','Only staff may take photographs',1,'','Photography is allowed only without flash.',25),
  (eid,s3,'mcq','Where does the tour stop after the clocks?','At the café','At the lockers','At the library','At the car park',0,'','The guide specifies twenty minutes in Room 14 before the café.',26),
  (eid,s3,'mcq','Where can children’s activity sheets be collected?','From the information desk','From the café','From Room 14','From the transport gallery',0,'','The guide mentions collecting sheets but gives no information about payment.',27),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: The tour begins in the ______ gallery.','','','','',0,'transport|transport gallery','The guide directs visitors to free lockers beside the entrance.',28),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: The clock exhibition is in Room ______.','','','','',0,'14|fourteen','Photography is allowed only without flash.',29),
  (eid,s3,'gap','Complete the summary with ONE OR TWO words: The café serves soup and ______ until three o’clock.','','','','',0,'sandwiches|sandwich','The guide specifies twenty minutes in Room 14 before the café.',30);
 INSERT INTO sections (exam_id,title,passage_title,passage_text,instruction,audio_url,sort_order) VALUES (eid,'Section 4','Changes to Local Transport','Presenter: From next Monday, the number 26 bus will no longer stop outside the old hospital. Use the new stop beside the public library instead. Services will run every fifteen minutes during the day and every thirty minutes after nine in the evening.
 INSERT INTO questions (exam_id,section_id,qtype,text,option_a,option_b,option_c,option_d,correct_option,accepted_answers,explanation,sort_order) VALUES
  (eid,s4,'tfng','The number 26 will stop beside the public library.','','','','',0,'','The presenter tells passengers to use the new library stop.',31),
  (eid,s4,'tfng','Evening buses after nine run every thirty minutes.','','','','',0,'','The presenter states a thirty-minute frequency after nine.',32),
  (eid,s4,'tfng','The cycle diversion passes through Willow Park.','','','','',0,'','The signed diversion goes through Willow Park.',33),
  (eid,s4,'mcq','Which stop will be removed?','The old hospital stop','The library stop','The theatre stop','The station stop',0,'','The presenter tells passengers to use the new library stop.',34),
