 INSERT INTO sections (exam_id,title,passage_title,passage_text,instruction,audio_url,sort_order) VALUES (eid,'Section 1','Choosing a University Course','Tutor: Before you select your modules, consider how you prefer to learn. The environmental-science course has one lecture and one field workshop each week. Assessment is sixty per cent coursework and forty per cent examination.
 INSERT INTO questions (exam_id,section_id,qtype,text,option_a,option_b,option_c,option_d,correct_option,accepted_answers,explanation,sort_order) VALUES
  (eid,s1,'tfng','The course includes a weekly field workshop.','','','','',0,'','The tutor describes one lecture and one field workshop weekly.',1),
  (eid,s1,'tfng','Most of the assessment is based on the examination.','','','','',1,'','Coursework is sixty per cent and examination forty per cent.',2),
  (eid,s1,'tfng','Statistics support is available on Thursday afternoons.','','','','',0,'','The tutor offers a Thursday support class and a library copy.',3),
  (eid,s1,'mcq','How many lectures are there each week?','One','Two','Three','Four',0,'','The tutor describes one lecture and one field workshop weekly.',4),
  (eid,s1,'mcq','What proportion is coursework?','Forty per cent','Fifty per cent','Sixty per cent','Eighty per cent',2,'','Coursework is sixty per cent and examination forty per cent.',5),
  (eid,s1,'mcq','Where can the student get the recommended textbook?','From the library','Only from the tutor','At the coastal reserve','It is unavailable',0,'','The tutor offers a Thursday support class and a library copy.',6),
  (eid,s1,'mcq','What should the student bring?','Waterproof boots and a notebook','A tent and cooking equipment','A new laptop','Measuring equipment',0,'','The tutor says measuring equipment is provided.',7),
  (eid,s1,'gap','Complete the summary with ONE OR TWO words: There is one lecture and one field ______ each week.','','','','',0,'workshop|field workshop','The tutor describes one lecture and one field workshop weekly.',8),
  (eid,s1,'gap','Complete the summary with ONE OR TWO words: The examination accounts for ______ per cent.','','','','',0,'forty|40|40 per cent|forty per cent','Coursework is sixty per cent and examination forty per cent.',9),
  (eid,s1,'gap','Complete the summary with ONE OR TWO words: The first field trip is on the second ______ of term.','','','','',0,'Friday|friday','The tutor offers a Thursday support class and a library copy.',10);
 INSERT INTO sections (exam_id,title,passage_title,passage_text,instruction,audio_url,sort_order) VALUES (eid,'Section 2','A Guided Museum Visit','Guide: Welcome to the City Museum. Today’s highlights tour begins in the transport gallery on the ground floor. Please leave large bags in the free lockers beside the entrance. Photography is allowed without flash.
 INSERT INTO questions (exam_id,section_id,qtype,text,option_a,option_b,option_c,option_d,correct_option,accepted_answers,explanation,sort_order) VALUES
  (eid,s2,'tfng','Large bags can be left in free lockers.','','','','',0,'','The guide directs visitors to free lockers beside the entrance.',11),
  (eid,s2,'tfng','Flash photography is permitted everywhere.','','','','',1,'','Photography is allowed only without flash.',12),
  (eid,s2,'tfng','The tour spends twenty minutes at the clock exhibition.','','','','',0,'','The guide specifies twenty minutes in Room 14 before the café.',13),
  (eid,s2,'mcq','Where are the lockers?','Beside the entrance','In Room 14','Next to the café','On the second floor',0,'','The guide directs visitors to free lockers beside the entrance.',14),
  (eid,s2,'mcq','What photography rule applies?','No photography','Photography without flash','Flash is required','Only staff may take photographs',1,'','Photography is allowed only without flash.',15),
  (eid,s2,'mcq','Where does the tour stop after the clocks?','At the café','At the lockers','At the library','At the car park',0,'','The guide specifies twenty minutes in Room 14 before the café.',16),
  (eid,s2,'mcq','Where can children’s activity sheets be collected?','From the information desk','From the café','From Room 14','From the transport gallery',0,'','The guide mentions collecting sheets but gives no information about payment.',17),
  (eid,s2,'gap','Complete the summary with ONE OR TWO words: The tour begins in the ______ gallery.','','','','',0,'transport|transport gallery','The guide directs visitors to free lockers beside the entrance.',18),
  (eid,s2,'gap','Complete the summary with ONE OR TWO words: The clock exhibition is in Room ______.','','','','',0,'14|fourteen','Photography is allowed only without flash.',19),
  (eid,s2,'gap','Complete the summary with ONE OR TWO words: The café serves soup and ______ until three o’clock.','','','','',0,'sandwiches|sandwich','The guide specifies twenty minutes in Room 14 before the café.',20);
