 INSERT INTO sections (exam_id,title,passage_title,passage_text,instruction,audio_url,sort_order) VALUES (eid,'Section 4','Community Sports Centre Enquiry','Receptionist: Good morning, Riverside Sports Centre. New members are welcome to visit for a free tour on weekday evenings. Our swimming pool opens at six in the morning, while the main sports hall opens at eight.
 INSERT INTO questions (exam_id,section_id,qtype,text,option_a,option_b,option_c,option_d,correct_option,accepted_answers,explanation,sort_order) VALUES
  (eid,s4,'tfng','Free tours are available on weekday evenings.','','','','',0,'','The receptionist offers free tours on weekday evenings.',31),
